# Prime Meridian: the foal learns to get up (foal-gym-v0, M-10).
#
# Registers "FoalGetUp" with MuJoCo Playground's env registry so
# `train_foal.py` and the RSL-RL CLI tools can train and play it.
#
# Body: creatures/bodies/horse.xml (generated by the game, loaded as-is).
# Task: dropped in a random pose, learn to roll onto the chest, prop up,
# and stand. See .crew/quests/foal-gym-v0.md for the full spec.

import dataclasses
import math as pymath
import pathlib

import mujoco
from mujoco_playground._src.rl import env_registry
from mujoco_playground._src.rl.rsl_rl import rsl_config
from reaf.simulation import torch as device
from reaf.simulation.torch import flat_scene as config
from reaf.simulation.torch import functional_reset
from reaf.simulation.torch import math as reaf_math
import torch

_BODY_PATH = pathlib.Path(__file__).resolve().parent.parent / "bodies" / "horse.xml"

JOINT_NAMES: tuple[str, ...] = (
    "neck-bend",
    "neck-pitch",
    "head-pitch",
    "head-roll",
    "fl-upper",
    "fl-lower",
    "fr-upper",
    "fr-lower",
    "hl-upper",
    "hl-lower",
    "hr-upper",
    "hr-lower",
)
NUM_JOINTS = len(JOINT_NAMES)

# Sites added at build time (read-only, for sensing feet/head height — not a
# change to bodies/horse.xml, which stays untouched on disk).
_FOOT_SITES: tuple[str, ...] = ("fl-foot", "fr-foot", "hl-foot", "hr-foot")
_FOOT_BODIES: tuple[str, ...] = ("fl-lower", "fr-lower", "hl-lower", "hr-lower")
_FOOT_LOCAL_POS = (0.0, 0.0, -0.37)  # matches the lower-leg capsule's far end
_HEAD_SITE = "head-tip"
_HEAD_BODY = "head"
_HEAD_LOCAL_POS = (0.24, 0.0, -0.1)  # matches the head capsule's far end

ROOT_JOINT_NAME = "root"

# Reward weights, in one place (quest rule).
REWARD_WEIGHTS: dict[str, float] = {
    "height": 3.0,
    "upright": 3.0,
    "head_height": 1.0,
    "feet_grounded": 1.0,
    "joint_speed": -0.01,
    "action_rate": -0.05,
    "energy": -0.001,
}

_STANDING_HEIGHT_RANGE = (0.75, 0.95)  # torso centre, metres; see quest's ~0.85m
_UPRIGHT_RANGE = (0.9, 1.0)
_HEAD_ABOVE_TORSO_RANGE = (0.15, 1.0)
_FOOT_GROUNDED_RANGE = (0.0, 0.08)

_CONTROL_TIMESTEP = 0.02
_SIMULATION_TIMESTEP = 0.002
_EPISODE_LENGTH_SECS = 6.0
_DROP_HEIGHT_RANGE = (0.4, 0.8)


def _load_base_scene() -> mujoco.MjSpec:
  """Loads horse.xml as-is, then adds read-only sites for feet/head sensing."""
  spec = mujoco.MjSpec.from_file(str(_BODY_PATH))
  for site_name, body_name in zip(_FOOT_SITES, _FOOT_BODIES):
    spec.body(body_name).add_site(name=site_name, pos=_FOOT_LOCAL_POS)
  spec.body(_HEAD_BODY).add_site(name=_HEAD_SITE, pos=_HEAD_LOCAL_POS)
  return spec


def _joint_ranges(spec: mujoco.MjSpec) -> torch.Tensor:
  """Reads each joint's [lo, hi] range from a compiled copy of the spec."""
  model = spec.copy().compile()
  ranges = [model.joint(name).range for name in JOINT_NAMES]
  return torch.tensor(ranges, dtype=torch.float32)


##
# Reset: drop from 0.4-0.8m, random orientation, random joint angles.
##


def reset_foal(
    dc,
    env_mask: torch.Tensor,
    joint_ranges: torch.Tensor,
    drop_height_range: tuple[float, float],
) -> None:
  """Drops the foal from a random height, orientation and joint pose."""
  data = dc.sim.data
  model = dc.sim.mj_model
  device_ = data.qpos.device
  n = data.qpos.shape[0]

  root = model.joint(ROOT_JOINT_NAME)
  fq, fv = int(root.qposadr[0]), int(root.dofadr[0])
  joint_q_adr = torch.tensor(
      [int(model.joint(jn).qposadr[0]) for jn in JOINT_NAMES],
      dtype=torch.long,
      device=device_,
  )
  joint_v_adr = torch.tensor(
      [int(model.joint(jn).dofadr[0]) for jn in JOINT_NAMES],
      dtype=torch.long,
      device=device_,
  )

  lo, hi = drop_height_range
  z = torch.rand(n, device=device_) * (hi - lo) + lo
  pos = torch.stack([torch.zeros(n, device=device_), torch.zeros(n, device=device_), z], dim=-1)

  # Uniform random orientation (Shoemake's method), quat = [w, x, y, z].
  u1 = torch.rand(n, device=device_)
  u2 = torch.rand(n, device=device_)
  u3 = torch.rand(n, device=device_)
  quat = torch.stack(
      [
          torch.sqrt(u1) * torch.cos(2 * pymath.pi * u3),
          torch.sqrt(1 - u1) * torch.sin(2 * pymath.pi * u2),
          torch.sqrt(1 - u1) * torch.cos(2 * pymath.pi * u2),
          torch.sqrt(u1) * torch.sin(2 * pymath.pi * u3),
      ],
      dim=-1,
  )

  ranges = joint_ranges.to(device_)
  joint_pos = torch.rand(n, NUM_JOINTS, device=device_) * (
      ranges[:, 1] - ranges[:, 0]
  ) + ranges[:, 0]

  mask_col = env_mask.unsqueeze(1)
  q_dtype, v_dtype = data.qpos.dtype, data.qvel.dtype

  data.qpos[:, fq : fq + 3] = torch.where(mask_col, pos.to(q_dtype), data.qpos[:, fq : fq + 3])
  data.qpos[:, fq + 3 : fq + 7] = torch.where(
      mask_col, quat.to(q_dtype), data.qpos[:, fq + 3 : fq + 7]
  )
  data.qvel[:, fv : fv + 6] = torch.where(
      mask_col, torch.zeros(n, 6, device=device_, dtype=v_dtype), data.qvel[:, fv : fv + 6]
  )
  data.qpos[:, joint_q_adr] = torch.where(
      mask_col, joint_pos.to(q_dtype), data.qpos[:, joint_q_adr]
  )
  data.qvel[:, joint_v_adr] = torch.where(
      mask_col,
      torch.zeros(n, NUM_JOINTS, device=device_, dtype=v_dtype),
      data.qvel[:, joint_v_adr],
  )


##
# Observations: only what his body can feel. No world position, no cheats.
##


def obs_gravity_b(f: dict[str, torch.Tensor]) -> torch.Tensor:
  """Gravity direction in the torso frame."""
  quat = f["torso/xquat"]
  gravity = torch.zeros_like(f["torso/xpos"])
  gravity[:, 2] = -1.0
  return reaf_math.quat_rotate_inverse(quat, gravity)


def obs_torso_ang_vel(f: dict[str, torch.Tensor]) -> torch.Tensor:
  """Torso angular velocity, already expressed in the torso (body) frame."""
  return f["torso/joint_vel"][:, 3:6]


##
# Rewards: getting up and staying up, nothing else.
##


def reward_height(f: dict[str, torch.Tensor]) -> torch.Tensor:
  return reaf_math.tolerance(f["torso/xpos"][:, 2], bounds=_STANDING_HEIGHT_RANGE, margin=0.3)


def reward_upright(f: dict[str, torch.Tensor]) -> torch.Tensor:
  up = torch.zeros_like(f["torso/xpos"])
  up[:, 2] = 1.0
  world_up = reaf_math.quat_rotate(f["torso/xquat"], up)
  return reaf_math.tolerance(world_up[:, 2], bounds=_UPRIGHT_RANGE, margin=0.5)


def reward_head_height(f: dict[str, torch.Tensor]) -> torch.Tensor:
  rel = f["head_site/xpos"][:, 2] - f["torso/xpos"][:, 2]
  return reaf_math.tolerance(rel, bounds=_HEAD_ABOVE_TORSO_RANGE, margin=0.3)


def reward_feet_grounded(f: dict[str, torch.Tensor]) -> torch.Tensor:
  heights = torch.stack([f[f"{name}/xpos"][:, 2] for name in _FOOT_SITES], dim=-1)
  return reaf_math.tolerance(heights, bounds=_FOOT_GROUNDED_RANGE, margin=0.1).mean(dim=-1)


def reward_joint_speed(f: dict[str, torch.Tensor]) -> torch.Tensor:
  return torch.sum(torch.square(f["robot/joint_vel"]), dim=-1)


def reward_action_rate(f: dict[str, torch.Tensor]) -> torch.Tensor:
  return torch.sum(torch.square(f["action"] - f["action_history"][:, 0]), dim=-1)


def reward_energy(f: dict[str, torch.Tensor]) -> torch.Tensor:
  return torch.sum(torch.abs(f["robot/actuator_force"]) * torch.abs(f["robot/joint_vel"]), dim=-1)


##
# Environment config.
##


def foal_getup_env(play: bool = False) -> config.Environment:
  """Foal get-up task: drop in a random pose, learn to stand."""
  del play  # No sim2real noise/randomization to disable yet (v0).

  base_scene = _load_base_scene()
  joint_ranges = _joint_ranges(base_scene)

  devices = {
      "robot": config.Component(
          device.ActuatorDevice,
          targets=list(JOINT_NAMES),
          measurements=["joint_pos", "joint_vel", "ctrl", "actuator_force"],
      ),
      "torso": config.Component(
          device.FreeDevice,
          body_name="torso",
          joint_name=ROOT_JOINT_NAME,
          measurements=["xpos", "xquat", "joint_vel"],
      ),
      "head_site": config.Component(device.SiteDevice, site_name=_HEAD_SITE),
  }
  for name in _FOOT_SITES:
    devices[name] = config.Component(device.SiteDevice, site_name=name)

  action_history_comp = config.Component(
      device.ActionHistory,
      key="action",
      history_length=1,
      feature_shape=(NUM_JOINTS,),
  )
  action_scale_comp = config.Component(
      device.processors.TransformActions,
      input_key="action",
      output_key="robot/ctrl",
      scale=((joint_ranges[:, 1] - joint_ranges[:, 0]) / 2.0),
      offset=((joint_ranges[:, 1] + joint_ranges[:, 0]) / 2.0),
      clip=(joint_ranges[:, 0], joint_ranges[:, 1]),
  )

  rewards = {
      "height": config.Reward(reward_height, weight=REWARD_WEIGHTS["height"]),
      "upright": config.Reward(reward_upright, weight=REWARD_WEIGHTS["upright"]),
      "head_height": config.Reward(reward_head_height, weight=REWARD_WEIGHTS["head_height"]),
      "feet_grounded": config.Reward(
          reward_feet_grounded, weight=REWARD_WEIGHTS["feet_grounded"]
      ),
      "joint_speed": config.Reward(reward_joint_speed, weight=REWARD_WEIGHTS["joint_speed"]),
      "action_rate": config.Reward(reward_action_rate, weight=REWARD_WEIGHTS["action_rate"]),
      "energy": config.Reward(reward_energy, weight=REWARD_WEIGHTS["energy"]),
  }

  policy_terms = {
      "joint_pos": config.Obs("robot/joint_pos").configure(output_shape=(NUM_JOINTS,)),
      "joint_vel": config.Obs("robot/joint_vel").configure(output_shape=(NUM_JOINTS,)),
      "gravity_b": config.Obs(obs_gravity_b).configure(output_shape=(3,)),
      "ang_vel": config.Obs(obs_torso_ang_vel).configure(output_shape=(3,)),
      "last_action": config.Obs("action").configure(output_shape=(NUM_JOINTS,)),
  }
  critic_terms = dict(policy_terms)
  critic_terms["torso_height"] = config.Obs("torso/xpos").configure(output_shape=(3,))

  observations = {
      "policy": config.ObsGroup(terms=policy_terms, enable_noise=False),
      "critic": config.ObsGroup(terms=critic_terms, enable_noise=False),
  }

  resetters = {
      "resetter": config.Component(
          functional_reset.FunctionalEnvironmentReset,
          terms=[
              config.Term(
                  reset_foal,
                  type="reset",
                  joint_ranges=joint_ranges,
                  drop_height_range=_DROP_HEIGHT_RANGE,
              )
          ],
      )
  }

  return config.Environment(
      base_scene=base_scene,
      device_layer=config.DeviceLayer(devices=devices),
      task_layer=config.TaskLayer(
          rewards=rewards,
          command_processors={"action_scale": action_scale_comp},
          command_feature_producers={"action_history": action_history_comp},
      ),
      observation_adapter=observations,
      resetters=resetters,
      sim=config.Sim(
          control_timestep=_CONTROL_TIMESTEP,
          simulation_timestep=_SIMULATION_TIMESTEP,
      ),
      episode_length_secs=_EPISODE_LENGTH_SECS,
      nan_termination=True,
  )


##
# RSL-RL runner config and registration.
##


@dataclasses.dataclass
class FoalGetUpRslRlOnPolicyRunnerCfg(rsl_config.RslRlOnPolicyRunnerCfg):
  """Config for FoalGetUp."""

  nworld: int = 4096  # fixed by the Nov 9 restart notes; don't search for max.
  max_iterations: int = 1000
  num_steps_per_env: int = 24
  save_interval: int = 50

  def __post_init__(self):
    self.actor.hidden_dims = (256, 128, 64)
    self.actor.obs_normalization = True
    self.actor.activation = "elu"
    self.actor.distribution_cfg = rsl_config.RslRlDistributionCfg(init_std=1.0)

    self.critic.hidden_dims = (256, 128, 64)
    self.critic.obs_normalization = True
    self.critic.activation = "elu"

    self.algorithm.value_loss_coef = 1.0
    self.algorithm.use_clipped_value_loss = True
    self.algorithm.clip_param = 0.2
    self.algorithm.entropy_coef = 0.005
    self.algorithm.num_learning_epochs = 5
    self.algorithm.num_mini_batches = 4
    self.algorithm.learning_rate = 1e-3
    self.algorithm.schedule = "adaptive"
    self.algorithm.gamma = 0.99
    self.algorithm.lam = 0.95
    self.algorithm.desired_kl = 0.01
    self.algorithm.max_grad_norm = 1.0


try:
  env_registry.register(
      "FoalGetUp",
      FoalGetUpRslRlOnPolicyRunnerCfg(),
      env_cfg_fn=foal_getup_env,
  )
except ValueError:
  pass  # Already registered (e.g. re-imported in the same process).
